"""VB-KVU-PF.1: a KPF-18 dry-run record (generated by the real runner's Run.finish against stubs, see
fixtures/kpf/generate_dryrun.py) carrying the KPF-17.x/18.x fields projects through claim_tuple.grade()."""
import json
import shutil
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "scripts" / "vidya"))
import claim_tuple as ct  # noqa: E402
from adapters import kv_prefix_fork as kpf  # noqa: E402

FX = Path(__file__).parent / "fixtures" / "kpf"


@pytest.fixture()
def sidecar(tmp_path):
    shutil.copytree(FX, tmp_path / "run")
    return tmp_path / "run" / "belief_measurements.jsonl"


def test_projects_dry_run_records_with_new_fields(sidecar):
    natives = kpf.native_rows(sidecar)
    assert len(natives) == 2
    tuples = [kpf.project(n) for n in natives]
    assert {t.extra["arm"] for t in tuples} == {"fork_on", "fork_on_dflash2_off"}  # off run no longer fork_on
    assert len({t.attestation_locator for t in tuples}) == 2
    for t in tuples:
        assert t.metric == "kpf_vs_fresh_first_token_top1_agree_fraction" and t.value == 1.0 and t.reps == 1
        assert t.attestation_present is True and t.protocol_id == ""
        ext = t.extra["kpf_ext"]
        assert set(ext) == set(kpf.EXT_KEYS)
        assert ext["hit_length_min"] == 120 and ext["hit_tokens"] == 120
        assert ext["hit_components"][0]["min"] == min(120, 120, 127)
        assert ext["tokens_lost_to_missing_checkpoint"] == 0 and ext["drafter_drop_kind"] == ["none"]
        assert ext["request_lane"] == ["completion_raw"] and ext["pinned_count"]["max"] == 2
        assert ext["cache_skip_control"] == {"requests_cache_prompt_false": 1, "cache_n_zero": 1}
        assert ext["checkpoint_set"][0]["positions"] == [120, 127]
        assert t.extra["unique_cells_peak"] == 4096  # no longer null outside item 7
        assert t.extra["decode_tok_s"]["aggregate"] == 50.0
        assert t.extra["equivalence"]["vs_fresh"]["max_abs_logit"] == 0.0  # canonical eq_summary names
        assert ct.grade(t)[:2] == ("Judged", "Located")  # shared ladder decides: n=1, no protocol


def test_registered_and_single_ladder():
    assert kpf.SOURCE_KIND in ct.registered()
    assert ct.source_classes()[kpf.SOURCE_KIND] == "measurement"
    assert list(ct.ladders()) .count("measurement") == 1


def test_mutated_rows_are_carried_as_absent_not_skipped(sidecar):
    rows = next((sidecar.parent / "rows").glob("*.jsonl"))
    rows.write_text(rows.read_text() + "x\n")
    natives = kpf.native_rows(sidecar)
    assert len(natives) == 2 and any(not n["attestation_present"] for n in natives)
    for n in natives:
        t = kpf.project(n)
        assert t.attestation_present is n["attestation_present"]
        assert ct.grade(t)[:2] == ("Judged", "Located")  # n=1, no protocol: the ladder's cap, not ours


def test_tampered_record_voids_file(sidecar):
    lines = sidecar.read_text().splitlines()
    rec = json.loads(lines[0])
    rec["host"] = "other"
    sidecar.write_text(json.dumps(rec) + "\n" + lines[1] + "\n")
    assert kpf.native_rows(sidecar) == ()


def test_unknown_arm_refused(sidecar):
    rec = json.loads(sidecar.read_text().splitlines()[0])
    rec["arm"] = "fork_both"
    assert any("arm" in p for p in kpf.validate_row(rec))


def test_missing_sidecar_is_zero_rows(tmp_path):
    assert kpf.native_rows(tmp_path / "nope.jsonl") == ()
